#include <stdio.h>

int main(void) {
    int sum = 0;
    for (int i = 0; i < 4; i++) {
        int num;
        scanf("%d", &num);
        if (num > 0) sum += num;
    }
    printf("%d\n", sum);
    return 0;
}

